// src/i18n/translations.js
// Diccionario de traducción. Etapa 1 (piloto): página de Ajustes, en es/en/pt.
// El resto de la app sigue en español fijo hasta que se traduzca página por página
// (evita traducir todo de una sola vez con alto riesgo de romper algo sin poder revisarlo).
//
// Convención de keys: 'seccion.subseccion.campo'. Si una key falta en el idioma
// activo, useT() cae a español, y si tampoco existe ahí, muestra la propia key
// (nunca un error ni una pantalla en blanco).

